oxy_webhelp_navlinks = {"iyi1686564616763-d2984e495":{"topics":[{"title":"Passive to active PWM transition","shortdesc":"<p class=\"shortdesc\">If the device enters safe state (LE1 failure reaction) with passive \t\tdischarge enabled, when the latched error detection is cleared by SPI reset command, the \t\tgate driver output stages are switched from passive discharge to active discharge within \t\t\t<span class=\"ph parameter-ifx\">t<sub class=\"ph sub\">PEN_PD<\/sub><\/span>.<\/p>","href":"bif1686564709698.html","attributes":{"data-id":"bif1686564709698"},"menu":{"hasChildren":false},"tocID":"bif1686564709698-d2984e503","topics":[]}]}};